// webrtc for the vault worker. workers have no RTCPeerConnection, so this stands in for get-webrtc
// (what hyper-webrtc uses) and forwards the setup to a real one in the page (page.js). a dedicated worker gets the
// data channel transferred, so the data goes from here straight to the other browser. a SharedWorker cant get it
// (see page.js), there every message goes through the page (the short hop page <-> worker is added then).
// it covers exactly what hyper-webrtc uses: the setup calls, onicecandidate, and its one negotiated data channel.
// the vault worker can serve many tabs (SharedWorker), one of them does the webrtc (use_page), when it closes
// its connections close too (drop_page) and the worker gives the job to another tab
const { make_tx } = require('iframe-runtime')
const { split, make_joiner } = require('./pieces')

// messages are { head, refs, type, data, meta }, a reply points to its call with refs.cause
const state = { next_id: 0, waiting: new Map(), peers: new Map(), page: null, tx: null }

module.exports = { RTCPeerConnection: make_peer, RTCIceCandidate: make_candidate, use_page, drop_page }

function use_page (port) {
  if (state.page) return
  state.page = port
  state.tx = make_tx('webrtc') // a new tab, so the heads start again
  port.postMessage(state.tx({ to: 'webrtc-page', type: 'rtc-page' })) // the tab shows it holds the connections
  port.addEventListener('message', on_message)
}

function drop_page (port) {
  if (state.page !== port) return
  port.removeEventListener('message', on_message)
  state.page = null
  for (const { reject } of state.waiting.values()) reject(new Error('the tab with the webrtc connection was closed'))
  state.waiting.clear()
  for (const id of [...state.peers.keys()]) on_event({ id, type: 'close', data: null, ready_state: 'closed' })
  state.peers.clear()
}

function make_peer (options) {
  const id = state.next_id++
  const record = { peer: null, channel: null }
  const peer = {
    onicecandidate: null,
    localDescription: null,
    createDataChannel,
    createOffer: () => ask(id, 'create_offer'),
    createAnswer: () => ask(id, 'create_answer'),
    setLocalDescription,
    setRemoteDescription: description => ask(id, 'set_remote_description', description),
    addIceCandidate: candidate => ask(id, 'add_ice_candidate', candidate),
    close: () => tell(id, 'close')
  }
  record.peer = peer
  state.peers.set(id, record)
  tell(id, 'create', { iceServers: options?.iceServers })
  return peer

  async function setLocalDescription (description) { peer.localDescription = await ask(id, 'set_local_description', description) }
  function createDataChannel (label, channel_options) {
    record.channel = make_channel(id)
    tell(id, 'create_channel', label, channel_options)
    return record.channel
  }
}

function make_candidate (candidate) { return { ...candidate } } // plain data is all the page needs

// a stand in for the data channel. once the page transferred the real one (use), it sends and gets the data itself
function make_channel (id) {
  const listeners = { open: new Set(), message: new Set(), error: new Set(), close: new Set() }
  let real = null
  return {
    readyState: 'connecting',
    addEventListener: (type, fn) => listeners[type].add(fn),
    removeEventListener: (type, fn) => listeners[type].delete(fn),
    send: data => real ? split(data).forEach(piece => real.send(piece)) : tell(id, 'send', data),
    close: () => real ? real.close() : tell(id, 'close_channel'),
    get transferred () { return !!real },
    use,
    listeners
  }
  function use (channel) {
    real = channel
    real.binaryType = 'arraybuffer'
    const on_piece = make_joiner(data => on_event({ id, type: 'message', data, ready_state: real.readyState }))
    real.addEventListener('message', e => on_piece(new Uint8Array(e.data)))
    for (const type of ['open', 'error', 'close']) real.addEventListener(type, () => on_event({ id, type, data: null, ready_state: real.readyState }))
  }
}

function ask (id, op, ...args) {
  if (!state.page) return Promise.reject(new Error('no tab to do webrtc'))
  const msg = state.tx({ to: 'webrtc-page', type: 'rtc', data: { id, op, args } })
  state.page.postMessage(msg)
  return new Promise((resolve, reject) => state.waiting.set(msg.head[2], { resolve, reject }))
}

function tell (id, op, ...args) { ask(id, op, ...args).catch(() => {}) }

function on_message (event) {
  const msg = event.data
  if (msg?.type === 'rtc-reply') return on_reply(msg.refs.cause[2], msg.data)
  if (msg?.type === 'rtc-event') return on_event(msg.data)
  if (msg?.type === 'rtc-channel') return on_channel(msg.data)
}

// the page made the data channel and transferred it here
function on_channel ({ id, channel }) {
  const record = state.peers.get(id)
  if (!record?.channel) return channel.close()
  record.channel.use(channel)
}

function on_reply (mid, { value, error }) {
  const waiting = state.waiting.get(mid)
  state.waiting.delete(mid)
  if (error) waiting?.reject(new Error(error))
  else waiting?.resolve(value)
}

// events of the real peer connection and data channel in the page
function on_event ({ id, type, data, ready_state }) {
  const record = state.peers.get(id)
  if (!record) return
  if (type === 'icecandidate') return record.peer.onicecandidate?.({ candidate: data })
  const channel = record.channel
  if (!channel) return
  channel.readyState = ready_state
  for (const fn of channel.listeners[type]) fn({ data })
  if (type === 'close') state.peers.delete(id)
}
